function installFollowBallFix() {
  let host = window;
  try { if (window.parent && window.parent.document) host = window.parent; } catch (_) {}
  const doc = host.document;
  try { host.__PKM_KANTO_FOLLOW_BALL_FIX_RUNTIME__?.destroy?.(); } catch (_) {}
  const key = '__PKM_KANTO_FOLLOW_BALL_FIX_V1321__';
  if (!doc || host[key]) return;
  host[key] = true;

  // 酒馆实卡：跟随伙伴替代精灵球；短按互动、长按直接打开面板、拖动移动。
  const style = doc.getElementById('pkm-kanto-follow-ball-fix-v1321') || doc.createElement('style');
  style.id = 'pkm-kanto-follow-ball-fix-v1321';
  style.textContent = '#pkm-kanto-ball.following .orb{display:none!important}';
  (doc.head || doc.documentElement).appendChild(style);

  const cleanups = [];
  const listen = (target, type, fn, opts) => {
    target.addEventListener(type, fn, opts);
    cleanups.push(() => target.removeEventListener(type, fn, opts));
  };
  let holdTimer = null, resetTimer = null, pointerId = null;
  let startX = 0, startY = 0, longPressed = false, swallowClick = false;
  const clearHold = () => { if (holdTimer !== null) host.clearTimeout(holdTimer); holdTimer = null; };
  const resetClick = () => {
    if (resetTimer !== null) host.clearTimeout(resetTimer);
    resetTimer = null; longPressed = false; swallowClick = false;
  };
  const openBallPanel = () => {
    try { if (typeof host.PKMKanto?.openPanel === 'function') { host.PKMKanto.openPanel(); return true; } } catch (_) {}
    // 旧桥接兼容；新桥接会走上面的公开 API。
    const orb = doc.querySelector('#pkm-kanto-ball .orb');
    if (orb) { orb.click(); return true; }
    return false;
  };
  listen(doc, 'pointerdown', e => {
    const img = e.target?.closest?.('#pkm-kanto-ball .follower');
    if (!img || !e.isPrimary || (e.pointerType === 'mouse' && e.button !== 0)) return;
    clearHold(); resetClick();
    pointerId = e.pointerId; startX = e.clientX; startY = e.clientY;
    holdTimer = host.setTimeout(() => {
      holdTimer = null;
      // 不检查按下时那一张 img 是否还连在 DOM 上：MVU 刷新可能重绘图片，
      // 只要当前仍有跟随伙伴就应按时打开面板。
      if (!doc.querySelector('#pkm-kanto-ball .follower')) return;
      longPressed = true; swallowClick = true;
      openBallPanel();
    }, 520);
  }, true);
  listen(doc, 'pointermove', e => {
    if (pointerId !== e.pointerId || holdTimer === null) return;
    const threshold = e.pointerType === 'touch' ? 14 : 8; // 容忍轻微手抖，明显移动才认作拖动
    if (Math.hypot(e.clientX - startX, e.clientY - startY) >= threshold) clearHold();
  }, true);
  listen(doc, 'pointerup', e => {
    if (pointerId !== e.pointerId) return;
    clearHold(); pointerId = null;
    if (longPressed) {
      resetTimer = host.setTimeout(() => { resetTimer = null; longPressed = false; swallowClick = false; }, 700);
    }
  }, true);
  listen(doc, 'pointercancel', e => {
    if (pointerId !== e.pointerId) return;
    clearHold(); pointerId = null; resetClick();
  }, true);
  listen(doc, 'click', e => {
    if (!swallowClick || !e.target?.closest?.('#pkm-kanto-ball .follower')) return;
    e.preventDefault(); e.stopPropagation(); e.stopImmediatePropagation();
    resetClick();
  }, true);
  const hint = () => {
    const img = doc.querySelector('#pkm-kanto-ball .follower');
    if (img && !img.dataset.followBallHint) {
      img.title = (img.title || '') + '；短按互动并听叫声；快速往返移动鼠标可抚摸；拖动可移动；长按打开队伍／仓库面板';
      img.dataset.followBallHint = '1';
    }
  };
  const observer = new host.MutationObserver(hint);
  observer.observe(doc.body || doc.documentElement, { childList: true, subtree: true });
  hint();
  host.__PKM_KANTO_FOLLOW_BALL_FIX_RUNTIME__ = {
    destroy() {
      clearHold(); resetClick(); observer.disconnect();
      for (const fn of cleanups.splice(0)) { try { fn(); } catch (_) {} }
      style.remove(); delete host[key];
    }
  };
}
